class MenuValidator:
    """Class to validate menu plans."""

    def __init__(self):
        self.validations = {'valid': True, 'errors': [], 'warnings': []}

    def read_menu_data(self, filepath: str) -> Dict:
        """Read menu data from JSON file."""
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                return json.load(f)
        except FileNotFoundError:
            return {'total_menus': 0, 'menus': []}

    def has_all_meals(self, day_menu: Dict) -> bool:
        """Check if daily menu has all three meals specified."""
        required_fields = ['day', 'breakfast', 'lunch', 'dinner', 'estate_calories', 'dietary_compliance_pct']
        missing = [f for f in required_fields if f not in day_menu or day_menu[f] is None]
        return len(missing) == 0

    def calories_in_range(self, total_calories: int) -> bool:
        """Check if calories are within reasonable range (1400-2800)."""
        return 1400 <= total_calories <= 2800

    def get_lunch_category(self, lunch_recipe: Dict) -> str:
        """Get the category of a lunch recipe."""
        category = lunch_recipe.get('category', '')
        return category.lower() if category else 'unknown'

    def consecutive_days_same_lunch_category(self, menu_data: Dict) -> List[Dict]:
        """Check if any two consecutive days have the same lunch category."""
        errors = []

        menus = menu_data.get('menus', [])
        for i in range(len(menus) - 1):
            current_cat = self.get_lunch_category(menus[i]['lunch'])
            next_cat = self.get_lunch_category(menus[i + 1]['lunch'])

            if current_cat == next_cat:
                errors.append({
                    'type': 'error',
                    'message': f"Consecutive same lunch category from {menus[i]['day']} to {menus[i+1]['day']}",
                    'details': {'current': current_cat, 'next': next_cat, 'day1': menus[i]['day'], 'day2': menus[i+1]['day']}
                })

        return errors

    def compliance_percentages_valid(self, menus: List[Dict]) -> List[Dict]:
        """Check if all compliance percentages are between 0 and 100."""
        errors = []

        for i, menu in enumerate(menus):
            compliance = menu.get('dietary_compliance_pct', 0)

            if not isinstance(compliance, (int, float)):
                errors.append({
