class MenuBuilder:
    """Class to build evidence-based weekly menus."""

    def __init__(self):
        self.recipes = []
        self.daily_menus = []

    def read_recipes(self, filepath: str) -> None:
        """Read recipes from JSON file."""
        try:
            with open(filepath, 'r') as f:
                self.recipes = json.load(f)
        except FileNotFoundError:
            pass

    def _get_category(self, recipe: Dict) -> str:
        """Extract recipe category from name."""
        name = recipe.get('name', '').lower()
        if 'vegeta' in name or 'cream' in name:
            return 'vegetable'
        if 'meat' in name:
            return 'meat'
        if 'soup' in name:
            return 'soup'
        return 'other'

    def _assess_evidence_score(self, recipe: Dict) -> int:
        """Assign evidence score (1-5) based on research alignment."""
        name = recipe.get('name', '').lower()
        cat = self._get_category(recipe)

        base_scores = {
            'vegetable': 5, 'soup': 4, 'breakfast': 3, 'staple': 3, 
            'meat': 3, 'other': 2
        }
        score = base_scores.get(cat, 3)

        # Vegetarian recipes get full score
        if 'vegeta' in name or 'veg' in name:
            score = 5

        return min(5, max(1, score))

    def _estimate_calories(self, recipe: Dict) -> int:
        """Estimate calories based on category."""
        cat = self._get_category(recipe)
        cal_by_cat = {
            'vegetable': 350, 'soup': 300, 'breakfast': 400, 'staple': 500,
            'meat': 650, 'other': 425
        }
        return cal_by_cat.get(cat, 425)

    def _assess_compliance(self, total_calories: int) -> float:
        """Calculate dietary compliance percentage."""
        if 1800 <= total_calories <= 2200:
            return 85.0
        if total_calories > 2200:
            return max(35, 85 - (total_calories - 2200) / 5)
        return min(100, 85 + (1800 - total_calories) / 10)

