        return sample_papers

    def run_analysis(self, output_file: str) -> None:
        """Run analysis and save results."""
        papers = self.read_research_papers({})
        processed_papers = self.search_papers(papers)

        with open(output_file, 'w', encoding='utf-8') as f:
            json.dump(processed_papers, f, ensure_ascii=False, indent=2)

        print(f"Processed {len(processed_papers)} papers and saved to {output_file}")
