    for paper in processed_papers[:10]:  # Show first 10
        print(f"Title: {paper['title']}")
        print(f"  Relevance: {paper['relevance_score']}/5, Confidence: {paper['confidence_level']}")
        print(f"  Dietary Focus: {paper['applicable_dietary_type']}")
