#!/usr/bin/env python3
"""
Build evidence-based weekly menus combining categorized recipes
with research findings to create scientifically grounded meal programs.
"""

import json
from typing import Dict, List

class MenuBuilder:
    """Class to build evidence-based weekly menus."""

    def __init__(self):
        self.categorized_recipes = []
        self.research_findings = []
        self.daily_menus = []

    def read_categorized_recipes(self, filepath: str) -> None:
        """Read categorized recipes from JSON file."""
        with open(filepath, 'r', encoding='utf-8') as f:
            self.categorized_recipes = json.load(f)

    def read_research_findings(self, filepath: str) -> None:
        """Read research findings from JSON file."""
        with open(filepath, 'r', encoding='utf-8') as f:
            self.research_findings = json.load(f)

    def _extract_category(self, recipe: Dict) -> str:
        """Extract category from recipe data."""
        category = recipe.get('category', '')
        return category.lower().replace('_', ' ')

    def _assess_evidence_score(self, recipe: Dict) -> int:
        """Assign evidence score (1-5) based on recipe alignment with research."""
        category = recipe.get('category', '').lower().replace('_', ' ')
        category_lower = category.lower()

        score = 3

        high_evidence = ['vegetarian', 'lunch', 'dietary', 'nutrition']
        medium_evidence = ['meal', 'soup']

        for c in high_evidence:
            if c in category_lower or c in recipe.get('name', '').lower():
                score = 5
                break

        for c in medium_evidence:
            if c in category_lower or c in recipe.get('name', '').lower():
                score = 4
                break

        return min(5, max(1, score))

    def _estimate_calories(self, recipe: Dict) -> int:
        """Estimate calories based on recipe category."""
        category = self._extract_category(recipe)
        calories_map = {
            'meat': 650,
            'vegetable': 350,
            'breakfast': 400,
            'soup': 300,
            'staple': 500
        }
        return calories_map.get(category, 400)

    def _assess_dietary_compliance(self, total_calories: int) -> float:
        """Calculate dietary compliance percentage."""
        if 1800 <= total_calories <= 2200:
            return 85.0
        elif total_calories > 2200:
            return max(0, 85 - (total_calories - 2200) / 10)
        else:
            return max(0, 85 + (1800 - total_calories) / 10)

    def add_menu(self, day: str, breakfast: str, lunch: Dict, dinner: Dict) -> None:
        """Add a daily menu entry."""
        total_calories = 400 + self._estimate_calories(lunch) + self._estimate_calories(dinner)
        compliance = self._assess_dietary_compliance(total_calories)

        self.daily_menus.append({
            'day': day,
            'breakfast': breakfast,
            'lunch': lunch,
            'dinner': dinner,
            'estate_calories': round(total_calories),
            'dietary_compliance_pct': round(compliance, 1)
        })

    def ensure_category_variation(self) -> tuple:
        """Ensure no two consecutive days have the same lunch category."""
        issues = []
        last_cat = None
        for i in range(len(self.daily_menus) - 1):
            cat = self._extract_category(self.daily_menus[i]['lunch'])
            if cat == last_cat:
                issues.append(f"{i+1}: Same category {cat}")
            last_cat = cat
        return issues

    def build_menus_from_data(self) -> None:
        """Build weekly menus from categorized recipes and research."""
        for recipe in self.categorized_recipes:
            recipe['evidence_score'] = self._assess_evidence_score(recipe)

        eaten_names = set()
        for day_num in range(5):
            # Pick a lunch recipe
            candidates = [r for r in self.categorized_recipes if 'high-protein' in r.get('dietary_tags', [])]
            if not candidates:
                candidates = self.categorized_recipes

            lunch_r = candidates[day_num % len(candidates)]
            if lunch_r['name'] in eaten_names:
                lunch_r = lunch_r

            # Pick a dinner recipe
            dinner_candidates = [r for r in self.categorized_recipes if 'vegetarian' in r.get('dietary_tags', [])]
            if not dinner_candidates:
                dinner_candidates = self.categorized_recipes

            dinner_r = dinner_candidates[day_num % len(dinner_candidates)]
            if dinner_r['name'] in eaten_names:
                dinner_r = dinner_candidates[0

            self.add_menu('Day ' + str(day_num + 1),
                          'Oatmeal with fruit', lunch_r, dinner_r)
            eaten_names.add(lunch_r['name'])
            eaten_names.add(dinner_r['name'])

        issues = self.ensure_category_variation()
        print(f"Built {len(self.daily_menus)} daily menus")
        for m in self.daily_menus:
            print(f"  {m['day']}: {m['breakfast']}, {m['lunch']['name']}, {m['dinner']['name']} "
                  f"(calories: {m['estate_calories']}, compliance: {m['dietary_compliance_pct']}%)")
        if issues:
            print("Category warnings:", ', '.join(issues))

    def save_output(self, output_path: str) -> None:
        """Save menus to JSON."""
        with open(output_path, 'w', encoding='utf-8') as f:
            json.dump({'total_days': len(self.daily_menus), 'menus': self.daily_menus}, f, ensure_ascii=False, indent=2)


def main():
    builder = MenuBuilder()
    builder.read_categorized_recipes('categorized_recipes.json')
    builder.read_research_findings('research_findings.json')
    builder.build_menus_from_data()
    builder.save_output('evidence_based_menus.json')

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
 """
 Validate evidence-based menus to ensure they meet all requirements:
 - Each day has all three meals specified
 - Estimated calories are within reasonable range (1400-2800)
 - No two consecutive days have the same lunch category
 - Dietary compliance percentages are between 0 and 100
"""

import json
from typing import Dict, List

class MenuValidator:
    """Class to validate menu plans."""

    def __init__(self):
        self.validations = {
            'valid': True,
            'errors': [],
            'warnings': []
        }

    def read_menu_data(self, filepath: str) -> Dict:
        """Read menu data from JSON file."""
        with open(filepath, 'r', encoding='utf-8') as f:
            return json.load(f)

    def has_all_meals(self, day_menu: Dict) -> bool:
        """Check if a daily menu has all three meals specified."""
        required_fields = ['day', 'breakfast', 'lunch', 'dinner', 
                          'estate_calories', 'dietary_compliance_pct']

        missing = []
        for field in required_fields:
            if field not in day_menu or day_menu[field] is None:
                missing.append(field)

        return len(missing) == 0

    def calories_in_range(self, total_calories: int) -> bool:
        """Check if calories are within reasonable range."""
        return 1400 <= total_calories <= 2800

    def get_lunch_category(self, lunch_recipe: Dict) -> str:
        """Get the category of a lunch recipe."""
        category = lunch_recipe.get('category', '')
        return category.lower().replace('_', ' ')

    def consecutive_days_same_lunch_category(self, menu_data: Dict) -> List[Dict]:
        """Check if any two consecutive days have the same lunch category."""
        errors = []

        if not menu_data or not menu_data.get('menus'):
            return errors

        menus = menu_data.get('menus', [])
        for i in range(len(menus) - 1):
            current_lunch = menus[i].get('lunch', {})
            next_lunch = menus[i + 1].get('lunch', {})

            current_cat = self.get_lunch_category(current_lunch)
            next_cat = self.get_lunch_category(next_lunch)

            if current_cat == next_cat:
                errors.append({
                    'type': 'error',
                    'message': f"Consecutive same lunch category from {menus[i]['day']} to {menus[i+1]['day']}",
                    'details': {'current': current_cat, 'next': next_cat, 'day1': menus[i]['day'], 'day2': menus[i+1]['day']}
                })

        return errors

    def compliance_percentages_valid(self, menus: List[Dict]) -> List[Dict]:
        """Check if all compliance percentages are between 0 and 100."""
        errors = []

        for i, menu in enumerate(menus):
            compliance = menu.get('dietary_compliance_pct', 0)

            if not isinstance(compliance, (int, float)):
                errors.append({
                    'type': 'error',
                    'message': f"Day {menu.get('day', i+1)}: dietary_compliance_pct must be a number",
                    'details': {'day': menu.get('day', i+1), 'value': compliance, 'index': i}
                })
            elif compliance < 0 or compliance > 100:
                errors.append({
                    'type': 'error',
                    'message': f"Day {menu.get('day', i+1)}: dietary_compliance_pct must be between 0 and 100",
                    'details': {'day': menu.get('day', i+1), 'value': compliance, 'index': i}
                })

        return errors

    def run_validations(self, menus: List[Dict]) -> Dict:
        """Run all validations and return results."""
        self.validations = {
            'valid': True,
            'errors': [],
            'warnings': []
        }

        total_calories = []

        # Validate each menu
        for i, menu in enumerate(menus):
            print(f"Validating day {menu.get('day', i+1)}...")

            # Check if all meals are specified
            if not self.has_all_meals(menu):
                self.validations['valid'] = False
                self.validations['errors'].append({
                    'type': 'error',
                    'message': f"Day {menu.get('day', i+1)}: Missing required meal fields",
                    'details': menu
                })
                print(f"  ✗ Missing required meal fields")
            else:
                print(f"  ✓ All meals specified")

            # Check calories are in range
            calories = menu.get('estate_calories', 0)
            total_calories.append(calories)

            if calories and not self.calories_in_range(calories):
                self.validations['valid'] = False
                self.validations['errors'].append({
                    'type': 'error',
                    'message': f"Day {menu.get('day', i+1)}: Calories {calories} outside range (1400-2800)",
                    'details': {'day': menu.get('day', i+1), 'calories': calories}
                })
                print(f"  ✗ Calories {calories} outside valid range (1400-2800)")
            else:
                valid_range = self.calories_in_range(calories)
                status = "✓" if valid_range else "✗"
                print(f"  {status} Calories in range: {calories}")

            # Check compliance percentage
            compliance = menu.get('dietary_compliance_pct', 0)
            if compliance < 0 or compliance > 100:
                self.validations['valid'] = False
                self.validations['errors'].append({
                    'type': 'error',
                    'message': f"Day {menu.get('day', i+1)}: Compliance {compliance} not between 0 and 100",
                    'details': {'day': menu.get('day', i+1), 'compliance': compliance}
                })
                print(f"  ✗ Compliance {compliance} not between 0 and 100")
            else:
                valid_compliance = 0 <= compliance <= 100
                status = "✓" if valid_compliance else "✗"
                print(f"  {status} Compliance valid: {compliance}%")

        # Check consecutive days same lunch category
        menu_data = {'menus': menus}
        category_issues = self.consecutive_days_same_lunch_category(menu_data)

        if category_issues:
            self.validations['valid'] = False
            for issue in category_issues:
                self.validations['errors'].append(issue)
                print(f"  ✗ {issue['message']}")
        else:
            print("  ✓ No consecutive same lunch categories")

        # Check all compliance percentages are valid
        compliance_issues = self.compliance_percentages_valid(menus)
        if compliance_issues:
            self.validations['valid'] = False
            for issue in compliance_issues:
                self.validations['errors'].append(issue)
                print(f"  ✗ {issue['message']}")
        else:
            print("  ✓ All compliance percentages valid")

        print("\n" + "=" * 50)
        if self.validations['valid']:
            print("✓ ADDITIONAL VALIDATIONS PASSED")
        else:
            print("✗ ADDITIONAL VALIDATIONS FAILED")

        # Calculate summary stats
        valid_count = self.validations['valid']
        error_count = len(self.validations['errors'])
        warning_count = len(self.validations['warnings'])

        return {
            'valid': valid_count is True,
            'errors': self.validations['errors'],
            'warnings': self.validations['warnings'],
            'summary': {
                'total_menus': len(menus),
                'calories_range': (min(total_calories), max(total_calories)) if total_calories else (None, None),
                'compliance_range': (min([m.get('dietary_compliance_pct', 0) for m in menus]), max([m.get('dietary_compliance_pct', 100) for m in menus])) if menus else (None, None),
                'meal_coverage': all(self.has_all_meals(m) for m in menus),
                'category_variety': error_count == 0  # No category issues
            }
        }

    def print_results(self, results: Dict) -> None:
        """Print validation results."""
        print("\n" + "=" * 60)
        print("VALIDATION RESULTS SUMMARY")
        print("=" * 60)

        if results['valid']:
            print("OVERALL STATUS: ✓ PASS")
        else:
            print("OVERALL STATUS: ✗ FAIL")

        print(f"\nDetailed Results:")
        print(f"  - Total menus validated: {results['summary']['total_menus']}")
        print(f"  - All meals present: {results['summary']['meal_coverage']}")
        print(f"  - No consecutive category repeats: {results['summary']['category_variety']}")
        print(f"  - Calories range: {results['summary']['calories_range']} kcal")
        print(f"  - Compliance % range: {results['summary']['compliance_range']}")

        if results['errors']:
            print(f"\n✗ ERRORS ({len(results['errors'])}):")
            for error in results['errors']:
                print(f"  - Error: {error['message']}")
        else:
            print(f"\n✓ NO ERRORS")


def main():
    validator = MenuValidator()

    # Read menu data
    print("Reading menu data from evidence_based_menus.json...")
    menu_data = validator.read_menu_data('evidence_based_menus.json')

    print(f"Found {len(menu_data.get('menus', []))} daily menus")

    # Run validations
    results = validator.run_validations(menu_data.get('menus', []))

    # Print results
    validator.print_results(results)

    # Save validation report
    with open('validation_report.json', 'w', encoding='utf-8') as f:
        json.dump(results, f, ensure_ascii=False, indent=2)

    print(f"\nValidation report saved to validation_report.json")

    if results['valid']:
        print("\n🎉 ALL VALIDATIONS PASSED!")
    else:
        print("\n❌ SOME VALIDATIONS FAILED")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Analyze research papers about workplace nutrition programs.
Extracts title, year, venue, citation count, summary, and assigns relevance scores.
"""

import json
from typing import Dict, List

class ResearchAnalyzer:
    """Class to analyze research papers."""

    def __init__(self):
        self.papers = []

    def search_papers(self, paper_data: List[Dict]) -> List[Dict]:
        """Process paper data and extract relevant information."""
        processed = []

        for paper in paper_data:
            if not paper:
                continue

            # Extract paper information
            title = paper.get('title', '').strip()
            if not title:
                continue

            pub_year = 2019  # Default year from abstract context
            venue = paper.get('venue', paper.get('journal', 'Unknown'))
            if not venue:
                venue = "Unknown"
            citations = paper.get('citations', 0)
            summary = self._extract_summary(paper.get('abstract', ''))

            # Determine relevance score based on workplace/employee focus
            relevance_score = self._assess_relevance(title, summary)

            # Assign confidence level based on citations
            confidence_level = self._assess_confidence(citations)

            # Assign dietary focus
            dietary_focus = self._assess_dietary_focus(title, summary)

            processed.append({
                'title': title,
                'pub_year': pub_year,
                'venue': venue,
                'citation_count': citations,
                'summary': summary,
                'relevance_score': relevance_score,
                'confidence_level': confidence_level,
                'applicable_dietary_type': dietary_focus
            })

        return processed

    def _extract_summary(self, abstract: str) -> str:
        """Extract key findings from abstract."""
        if not abstract:
            return "Evaluation of workplace nutrition interventions"

        findings = []

        text_lower = abstract.lower()
        if "workplace" in text_lower and "nutrition" in text_lower:
            findings.append("Evaluation of workplace nutrition interventions")

        if "employee" in text_lower:
            findings.append("Employee health outcomes and dietary changes")

        if "lunch" in text_lower or "planner" in text_lower:
            findings.append("Lunch program effectiveness")

        if "health" in text_lower:
            findings.append("Health improvements from nutritional programs")

        if "dietary" in text_lower:
            findings.append("Dietary pattern changes in workplace settings")

        return "; ".join(findings[:3])

    def _assess_relevance(self, title: str, summary: str) -> int:
        """
        Assign relevance score (1-5) based on workplace/employee focus.
        5 = Most directly about workplace/employee nutrition programs
        """
        score = 0

        # Title indicators - weighted factors
        if 'workplace' in title.lower():
            score += 4
        if 'nutrition' in title.lower() or 'diet' in title.lower():
            score += 3
        if 'lunch' in title.lower():
            score += 3
        if 'employee' in title.lower():
            score += 2

        # Summary indicators
        summary_lower = summary.lower()
        if 'nutrition' in summary_lower:
            score += 2
        if 'lunch' in summary_lower or 'quality' in summary_lower:
            score += 1
        if 'dietary' in summary_lower or 'eating' in summary_lower:
            score += 1

        # Cap at 5
        return min(5, max(0, score))

    def _assess_confidence(self, citations: int) -> str:
        """
        Assign confidence level based on citation count.
        """
        if citations >= 100:
            return "High"
        elif citations >= 20:
            return "Medium"
        else:
            return "Low"

    def _assess_dietary_focus(self, title: str, summary: str) -> str:
        """
        Determine which dietary category the finding most applies to.
        """
        title_lower = title.lower()
        summary_lower = summary.lower()

        # Check for specific dietary focus
        if 'sodium' in title_lower or 'sodium' in summary_lower or 'salt' in title_lower:
            return 'sodium'
        if 'protein' in title_lower or 'protein' in summary_lower:
            return 'protein'
        if 'fiber' in title_lower or 'fiber' in summary_lower or 'whole grain' in title_lower:
            return 'fiber'
        if 'lunch' in title_lower or 'lunch' in summary_lower:
            return 'lunch'
        if 'nutrition' in title_lower or 'nutrition' in summary_lower:
            return 'nutrition'
        if 'dietary' in title_lower or 'dietary' in summary_lower:
            return 'dietary'

        return 'general'

    def read_research_papers(self, config: Dict[str, any]) -> List[Dict]:
        """
        Read research paper data from configuration or source.
        """
        # Sample research papers for simulation based on workplace nutrition program research
        sample_papers = [
            {
                'title': "Workplace Nutrition Intake from Lunch: Reflections on Socioecological Patterns",
                'abstract': 'Purpose: Evaluation of lunch programs in workplace settings and their integration into daily nutritional patterns.',
                'venue': 'Journal of Workplace Nutrition Research',
                'citations': 245
            },
