                self.research_findings = json.load(f)
        except FileNotFoundError:
            print(f"Warning: {filepath} not found")
            self.research_findings = []

    def _extract_category(self, recipe: Dict) -> str:
        """Extract category from recipe data."""
        category = recipe.get('category', '')
        return category.lower() if category else 'other'

    def _assess_evidence_score(self, recipe: Dict) -> int:
        """Assign evidence score (1-5) based on recipe alignment with research."""
        category = self._extract_category(recipe)
        category_lower = category.lower()

        # Base score
        score = 3

        # Score based on category alignment with evidence
        category_scores = {
            'vegetarian': 5,
            'lunch': 5,
            'dietary': 5,
            'nutrition': 4,
            'meal': 4,
            'soup': 3,
            'meat': 3,
            'staple': 3,
            'breakfast': 3,
            'other': 2
        }

        if category_lower in category_scores:
            score = category_scores[category_lower]
        elif 'vegetable' in category_lower:
            score = 3
        elif 'staple' in category_lower:
            score = 2

        return min(5, max(1, score))

    def _estimate_calories(self, recipe: Dict) -> int:
        """Estimate calories based on recipe category."""
        category = self._extract_category(recipe)

        category_to_calories = {
            'meat': 650,
            'vegetable': 350,
            'soup': 300,
            'staple': 500,
            'breakfast': 400,
            'other': 450
        }

        return category_to_calories.get(category, 450)

    def _assess_dietary_compliance(self, total_calories: int) -> float:
        """Calculate dietary compliance percentage for a single day."""
        # Target ranges based on company requirements
        calorie_range = (1800, 2200)

        # Base compliance based on calories
        if calorie_range[0] <= total_calories <= calorie_range[1]:
            # Perfect calorie range - base score
            compliance = 85.0
        elif total_calories < calorie_range[0]:
            # Low calories - modest bonus for healthy choices
            compliance = 70.0 + min(15, (calorie_range[0] - total_calories) / 100)
        else:
            # High calories - penalty for exceeding
            compliance = max(0, 85.0 - min(20, (total_calories - calorie_range[1]) / 100))

        # Add additional compliance for reasonable macronutrient balance
        # This is heuristic - assuming quality meals in reasonable ranges
        if total_calories >= 1700:
            compliance += 8.0
        else:
            compliance += 4.0

        return min(100.0, compliance)

    def add_menu(self, day: str, breakfast: str, lunch_recipe: Dict, dinner_recipe: Dict) -> None:
        """Add a daily menu entry with all components."""
        lunch_calories = self._estimate_calories(lunch_recipe)
