import json
from typing import Dict, List

class MenuValidator:
    """Class to validate menu plans."""

    def __init__(self):
        self.validations = {'valid': True, 'errors': [], 'warnings': []}

    def read_menu_data(self, filepath: str) -> Dict:
        """Read menu data from JSON file."""
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                return json.load(f)
        except FileNotFoundError:
            return {'total_menus': 0, 'menus': []}

    def has_all_meals(self, day_menu: Dict) -> bool:
        """Check if daily menu has all three meals specified."""
        required_fields = ['day', 'breakfast', 'lunch', 'dinner', 'estate_calories', 'dietary_compliance_pct']
        missing = [f for f in required_fields if f not in day_menu or day_menu[f] is None]
        return len(missing) == 0

    def calories_in_range(self, total_calories: int) -> bool:
        """Check if calories are within reasonable range (1400-2800)."""
        return 1400 <= total_calories <= 2800

    def get_lunch_category(self, lunch_recipe: Dict) -> str:
        """Get the category of a lunch recipe."""
        category = lunch_recipe.get('category', '')
        return category.lower() if category else 'unknown'

    def consecutive_days_same_lunch_category(self, menu_data: Dict) -> List[Dict]:
        """Check if any two consecutive days have the same lunch category."""
        errors = []

        menus = menu_data.get('menus', [])
        for i in range(len(menus) - 1):
            current_cat = self.get_lunch_category(menus[i]['lunch'])
            next_cat = self.get_lunch_category(menus[i + 1]['lunch'])

            if current_cat == next_cat:
                errors.append({
                    'type': 'error',
                    'message': f"Consecutive same lunch category from {menus[i]['day']} to {menus[i+1]['day']}",
                    'details': {'current': current_cat, 'next': next_cat, 'day1': menus[i]['day'], 'day2': menus[i+1]['day']}
                })

        return errors

    def compliance_percentages_valid(self, menus: List[Dict]) -> List[Dict]:
        """Check if all compliance percentages are between 0 and 100."""
        errors = []

        for i, menu in enumerate(menus):
            compliance = menu.get('dietary_compliance_pct', 0)

            if not isinstance(compliance, (int, float)):
                errors.append({
                    'type': 'error',
                    'message': f"Day {menu.get('day', i+1)}: dietary_compliance_pct must be a number",
                    'details': {'day': menu.get('day', i+1), 'index': i}
                })
            elif compliance < 0 or compliance > 100:
                errors.append({
                    'type': 'error',
                    'message': f"Day {menu.get('day', i+1)}: dietary_compliance_pct must be between 0 and 100",
                    'details': {'day': menu.get('day', i+1), 'value': compliance, 'index': i}
                })

        return errors

    def run_validations(self, menus: List[Dict]) -> Dict:
        """Run all validations and return results."""
        self.validations = {'valid': True, 'errors': [], 'warnings': []}

        total_calories = []

        for i, menu in enumerate(menus):
            print(f"Validating {menu.get('day', i+1)}...")

            if not self.has_all_meals(menu):
                self.validations['valid'] = False
                self.validations['errors'].append({
                    'type': 'error',
                    'message': f"Day {menu.get('day', i+1)}: Missing required meal fields",
                    'details': menu
                })
                print(f"  ✗ Missing required meal fields")
            else:
                print(f"  ✓ All meals specified")

            # Check calories
            calories = menu.get('estate_calories', 0)
            total_calories.append(calories)

            if calories and not self.calories_in_range(calories):
                self.validations['valid'] = False
                self.validations['errors'].append({
                    'type': 'error',
                    'message': f"Day {menu.get('day', i+1)}: Calories {calories} outside range (1400-2800)",
                    'details': {'day': menu.get('day', i+1), 'calories': calories}
                })
                print(f"  ✗ Calories {calories} out of range")
            else:
                print(f"  ✓ Calories: {calories}")

            # Check compliance
            compliance = menu.get('dietary_compliance_pct', 0)
            if compliance < 0 or compliance > 100:
                self.validations['valid'] = False
                self.validations['errors'].append({
                    'type': 'error',
                    'message': f"Day {menu.get('day', i+1)}: Compliance {compliance} not in [0,100]",
                    'details': {'day': menu.get('day', i+1), 'compliance': compliance}
                })
                print(f"  ✗ Compliance {compliance} out of range [0,100]")
            else:
                print(f"  ✓ Compliance: {compliance}%")

        # Check consecutive category repeats
        category_issues = self.consecutive_days_same_lunch_category({'menus': menus})
        if category_issues:
            self.validations['valid'] = False
            for issue in category_issues:
                self.validations['errors'].append(issue)
                print(f"  ✗ {issue['message']}")
        else:
            print(f"  ✓ No consecutive same categories")

        return self.validations

    def print_results(self, results: Dict) -> None:
        """Print validation results."""
        print("\n" + "=" * 60)
        if results['valid']:
            print("VALIDATION RESULTS: ALL VALIDATIONS PASSED ✓")
        else:
            print("VALIDATION RESULTS: VALIDATIONS FAILED ✗")

        print(f"\nSummary: Total menus validated: {len(results['warnings']) + len(results['errors'])}")
        if results['errors']:
            print(f"Errors: {len(results['errors'])}")
            for error in results['errors']:
