#!/usr/bin/env python3
"""
Build evidence-based weekly menus combining categorized recipes
with research findings to create scientifically grounded meal programs.
"""

import json
from typing import Dict, List

class MenuBuilder:
    """Class to build evidence-based weekly menus."""

    def __init__(self):
        self.categorized_recipes = []
        self.research_findings = []
        self.daily_menus = []

    def read_categorized_recipes(self, filepath: str) -> None:
        """Read categorized recipes from JSON file."""
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                self.categorized_recipes = json.load(f)
        except FileNotFoundError:
            print(f"Warning: {filepath} not found")
            self.categorized_recipes = []

    def read_research_findings(self, filepath: str) -> None:
        """Read research findings from JSON file."""
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                self.research_findings = json.load(f)
        except FileNotFoundError:
            print(f"Warning: {filepath} not found")
            self.research_findings = []

    def _extract_category(self, recipe: Dict) -> str:
        """Extract category from recipe data."""
        category = recipe.get('category', '')
        return category.lower() if category else 'other'

    def _assess_evidence_score(self, recipe: Dict) -> int:
        """Assign evidence score (1-5) based on research alignment."""
        category = self._extract_category(recipe)
        category_lower = category.lower()
        name_lower = recipe.get('name', '').lower()

        score = 3  # Base score

        # High evidence keywords
        high_evidence = ['vegetarian', 'lunch', 'dietary']
        medium_evidence = ['nutrition', 'meal', 'sodium', 'protein', 'fiber']

        for kw in high_evidence:
            if kw in category_lower or kw in name_lower:
                score = 5
                break

        for kw in medium_evidence:
            if kw in category_lower or kw in name_lower and score < 5:
                score = 4
                break

        return min(5, max(0, score))

    def _estimate_calories(self, recipe: Dict) -> int:
        """Estimate calories based on recipe category."""
        category = self._extract_category(recipe)

        calories_by_category = {
            'vegetarian': 350,
            'meat': 650,
            'soup': 300,
            'breakfast': 400,
            'staple': 500,
            'other': 425
        }

        return calories_by_category.get(category, 425)

    def _assess_dietary_compliance(self, total_calories: int) -> float:
        """Calculate dietary compliance percentage (0-100)."""
        target_low, target_high = 1800, 2200

        if target_low <= total_calories <= target_high:
            return 85.0
        elif total_calories > target_high:
            excess = total_calories - target_high
            return max(50, 85 - min(35, excess / 10))
        else:
            deficit = target_low - total_calories
            return min(100, 85 + min(20, deficit / 50))

    def add_menu(self, day: str, breakfast: str, lunch_recipe: Dict, dinner_recipe: Dict) -> None:
        """Add a daily menu entry."""
        lunch_cal = self._estimate_calories(lunch_recipe)
        dinner_cal = self._estimate_calories(dinner_recipe)
        total_calories = 400 + lunch_cal + dinner_cal

        self.daily_menus.append({
            'day': day,
            'breakfast': breakfast,
            'lunch': lunch_recipe,
            'dinner': dinner_recipe,
            'estate_calories': int(total_calories),
            'dietary_compliance_pct': round(self._assess_dietary_compliance(total_calories) * 10)
        })

    def categorize_recipes_for_menu(self) -> Dict[str, List[Dict]]:
        """Organize recipes by dietary category."""
        categories = {
            'vegetarian': [],
            'meat': [],
            'soup': [],
            'staple': [],
            'breakfast': [],
            'other': []
        }

        for recipe in self.categorized_recipes:
            cat = self._extract_category(recipe)
            if cat in categories:
                recipe['evidence_score'] = self._assess_evidence_score(recipe)
                recipe['category_display'] = cat.title()
                categories[cat].append(recipe)
            else:
                categories['other'].append(recipe)

        return categories

    def build_variety_menus(self) -> None:
        """Build menus ensuring category variation across days."""
        print("Building evidence-based weekly menus...")

        if not self.categorized_recipes:
            print("No recipes to build from")
            return

        # Get all recipe names that can be used
        all_recipe_names = set(r.get('name', '') for r in self.categorized_recipes)

        # Select 5 different recipes for lunch (prioritize by evidence score)
        day_names = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday']

        selected_lunches = []
        used_names = set()

        # Process recipes by category to ensure variety
        categories = self.categorize_recipes_for_menu()

        for day_idx, day in enumerate(day_names):
            # Get available lunch recipes (not used yet)
            available_lunches = []
            for cat, recipes in categories.items():
                for recipe in recipes:
                    if recipe.get('name', '') not in used_names:
                        available_lunches.append(recipe)

            # Prefer vegetarian and low-sodium options for health
            available_sorted = sorted(available_lunches, 
                                    key=lambda x: (x.get('evidence_score', 1) or 1, 
                                                  'vegetarian' in str(x).lower(),
                                                  len(x.get('dietary_tags', [])))
                                   )

            if available_sorted:
                lunch_recipe = available_sorted[0]
            else:
                lunch_recipe = self.categorized_recipes[0] if self.categorized_recipes else {}

            selected_lunches.append(lunch_recipe)
            used_names.add(lunch_recipe.get('name', ''))

            # For dinner, use different recipes if available
            available_dinners = []
            for r in self.categorized_recipes:
                if r.get('name', '') not in used_names and r != lunch_recipe:
                    available_dinners.append(r)

            if available_dinners:
                # Sort by evidence score and dietary tags
                available_sorted_d = sorted(available_dinners,
                                          key=lambda x: (x.get('evidence_score', 1) or 1, 
                                                        'vegetarian' not in str(x).lower(),
                                                        -len(x.get('dietary_tags', [])))
                                         )
                dinner_recipe = available_sorted_d[0]
            else:
                dinner_recipe = lunch_recipe  # Same if limited options

            # Breakfast rotation
            breakfast_patterns = ['Oatmeal with fruit', 'Whole grain toast with egg', 'Greek yogurt with berries']
            breakfast = breakfast_patterns[day_idx % 3]

            self.add_menu(day, breakfast, lunch_recipe, dinner_recipe)

        # Print menu summary
        print("=== EVIDENCE-BASED WEEKLY MENUS ===")
        for menu in self.daily_menus:
            print(f"Day: {menu['day']}")
            print(f"  Breakfast: {menu['breakfast']} (400 kcal)")
            print(f"  Lunch: {menu['lunch']['name']} "
                  f"[Cat: {menu['lunch'].get('category_display', 'unknown')} | Evidence: {menu['lunch'].get('evidence_score', 'N/A')}/5]")
            print(f"  Dinner: {menu['dinner']['name']} "
                  f"[Cat: {menu['dinner'].get('category_display', 'unknown')} | Evidence: {menu['dinner'].get('evidence_score', 'N/A')}/5]")
            print(f"  Total Calories: {menu['estate_calories']} | Compliance: {menu['dietary_compliance_pct']}%")

        # Check for consecutive category repeats
        category_counts = {}
        for menu in self.daily_menus:
            cat = menu['lunch'].get('category_display', 'unknown')
            category_counts[cat] = category_counts.get(cat, 0) + 1

        if any(count > 1 for count in category_counts.values()):
            print("\nAttention: Some categories appear multiple times")
        else:
            print("\n✓ Menu categories show good variety")

    def save_output(self, output_path: str = 'evidence_based_menus.json') -> None:
        """Save menu data to JSON file."""
        try:
            with open(output_path, 'w', encoding='utf-8') as f:
                json.dump({
                    'total_days': len(self.daily_menus),
                    'menus': self.daily_menus
                }, f, ensure_ascii=False, indent=2)
            print(f"Menus saved to {output_path}")
        except Exception as e:
            print(f"Error saving menu data: {e}")


def main():
    builder = MenuBuilder()
    builder.read_categorized_recipes('categorized_recipes.json')
    builder.read_research_findings('research_findings.json')
    builder.build_variety_menus()
    builder.save_output()


if __name__ == "__main__":
    main()

