            'vegetable': 4,
            'soup': 4,
            'staple': 3,
            'breakfast': 3,
            'meat': 3,
            'other': 2
        }

        score = category_scores.get(category, 3)

        # High score for vegetarian recipes
        if 'vegeta' in name or 'veg' in name:
            return 5

        # Bonus for low-sodium components
