#!/usr/bin/env python3
"""
Build evidence-based weekly menus combining categorized recipes
with research findings to create scientifically grounded meal programs.
"""

import json
from typing import Dict, List

class MenuBuilder:
    """Class to build evidence-based weekly menus."""

    def __init__(self):
        self.recipes = []
        self.daily_menus = []

    def read_recipes(self, filepath: str) -> None:
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                self.recipes = json.load(f)
        except FileNotFoundError:
            self.recipes = []

    def _get_category(self, recipe: Dict) -> str:
        name = recipe.get('name', '').lower()
        if 'vegetable' in name or 'cream' in name or 'basil' in name:
            return 'vegetable'
        if 'meat' in name or 'protein' in name:
            return 'meat'
        if 'soup' in name: return 'soup'
        if 'rice' in name or 'toast' in name or 'noodle' in name: return 'staple'
        return 'other'

    def _assess_evidence_score(self, recipe: Dict) -> int:
        name = recipe.get('name', '').lower()
        cat = self._get_category(recipe)
        scores = {'vegetable': 5, 'soup': 4, 'staple': 3, 'breakfast': 3, 'meat': 3, 'other': 2}
        score = scores.get(cat, 3)
        if 'vegeta' in name or 'veg' in name: score = 5
        return min(5, max(1, score))

    def _estimate_calories(self, recipe: Dict) -> int:
        cat = self._get_category(recipe)
        cal_map = {'vegetable': 350, 'soup': 300, 'breakfast': 400, 'staple': 500, 'meat': 650, 'other': 425}
        return cal_map.get(cat, 425)

    def _assess_compliance(self, total_calories: int) -> float:
        if 1800 <= total_calories <= 2200: return 100.0
        if total_calories > 2200: return max(40, 100 - (total_calories-2200)/4)
        return min(100, 100 + (1800-total_calories)/4)

    def add_menu(self, day: str, breakfast: str, lunch: Dict, dinner: Dict) -> None:
        total_calories = 400 + self._estimate_calories(lunch) + self._estimate_calories(dinner)
        self.daily_menus.append({
            'day': day, 'breakfast': breakfast, 'lunch': lunch, 'dinner': dinner,
            'estate_calories': int(total_calories), 'dietary_compliance_pct': round(self._assess_compliance(total_calories) * 10)
        })

    def _name_str(self, recipe: Dict) -> str:
        return str(recipe.get('name', ''))

    def _find_unique(self, used: set, recipes: List) -> tuple:
        """Find unique recipe not in used."""
        available = [(i, r) for i, r in enumerate(recipes) if self._name_str(r) not in used]
        if available:
            return available[-1]
        return (0, recipes[0] if recipes else {})

    def add_unique_lunch(self, used: set, day_idx: int, recipes: List) -> tuple:
        """Add unique lunch for day ensuring variety."""
        sorted_avail = sorted([(i, r) for i, r in enumerate(recipes) if self._name_str(r) not in used], 
                            key=lambda x: x[1].get('evidence_score', 3), reverse=True)
        if sorted_avail:
            lunch = sorted_avail[day_idx % len(sorted_avail)][1]
            used.add(self._name_str(lunch))
            # Find dinner
            dinner_options = [(i, r) for i, r in enumerate(recipes) if r != lunch and self._name_str(r) not in used]
            if dinner_options:
                dinner = sorted(dinner_options, key=lambda x: x[1].get('evidence_score', 3))[1] if len(sorted(dinner_options)) > 1 else dinner_options[0][1]
            else:
                dinner = lunch
            return lunch, dinner
        return recipes[0], recipes[1] if len(recipes) > 1 else recipes[0]

    def build_menu_week(self) -> List[Dict]:
        if not self.recipes: return []
        used_recipes = set()
        day_names = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday']
        breakfasts = ['Oatmeal with fruit', 'Whole grain toast with egg', 'Greek yogurt with berries']

        for day_idx, day in enumerate(day_names):
            lunch, dinner = self.add_unique_lunch(used_recipes, day_idx, self.recipes)
            bfs = breakfasts[day_idx % 3]
            self.add_menu(day, bfs, lunch, dinner)
        return self.daily_menus

    def print_menu_summary(self):
        print("\n=== EVIDENCE-BASED WEEKLY MENUS ===")
        for m in self.daily_menus:
            cat1 = self._get_category(m['lunch'])
            cat2 = self._get_category(m['dinner'])
            print(f"Day {m['day']}: {m['breakfast']}, {m['lunch']['name']} [{cat1}, {m['lunch'].get('evidence_score','N/A')}], {m['dinner']['name']} [{cat2}, {m['dinner'].get('evidence_score','N/A')}] (Cals: {m['estate_calories']}, Comp: {m['dietary_compliance_pct']}%)")

    def save_menus(self, filename: str = 'evidence_based_menus.json') -> None:
        try:
            with open(filename, 'w', encoding='utf-8') as f:
                json.dump({'menus': self.daily_menus}, f, ensure_ascii=False, indent=2)
            print(f"Saved to {filename}")
        except Exception as e:
            print(f"Error: {e}")


def main():
    b = MenuBuilder()
    b.read_recipes('categorized_recipes.json')
    b.build_menu_week()
    b.print_menu_summary()
    b.save_menus()


if __name__ == "__main__":
    main()

