"""

import json
from typing import Dict, List

class MenuValidator:
    """Validate menu completeness and correctness."""

    def __init__(self):
        self.results = {'valid': True, 'errors': []}

    def read_menus(self, filepath: str) -> List[Dict]:
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                data = json.load(f)
            return data.get('menus', [])
        except FileNotFoundError:
            return []

    def has_all_meals(self, menu: Dict) -> bool:
        """Check required fields are present."""
        req = ['day', 'breakfast', 'lunch', 'dinner', 'estate_calories', 'dietary_compliance_pct']
        return all(f in menu and menu[f] is not None for f in req)

    def calories_in_range(self, calories: int) -> bool:
        """Check calories are within 1400-2800."""
        return 1400 <= calories <= 2800

    def calc_category(self, recipe: Dict) -> str:
        """Get recipe category."""
        name = recipe.get('name', '').lower()
        if 'vegeta' in name or 'crea' in name: return 'vegetable'
        if 'meat' in name: return 'meat'
        if 'soup' in name: return 'soup'
        return 'other'

    def consecutive_same_category(self, menus: List[Dict]) -> List[Dict]:
        """Find consecutive days with same lunch category."""
        bad = []
        for i in range(len(menus) - 1):
            run1 = self.calc_category(menus[i]['lunch'])
            run2 = self.calc_category(menus[i+1]['lunch'])
            if run1 == run2:
                bad.append({'day1': menus[i]['day'], 'day2': menus[i+1]['day'], 'category': run1})
        return bad

    def validate_compliance(self, menus: List[Dict]) -> List[Dict]:
        """Check compliance is between 0 and 100."""
        bad = []
        for i, m in enumerate(menus):
            comp = m.get('dietary_compliance_pct')
            if not isinstance(comp, (int, float)) or comp < 0 or comp > 100:
                bad.append({'day': m.get('day'), 'value': comp})
        return bad

