                self.results['valid'] = False
                self.results['errors'].append(f"Day {m.get('day', i+1)}: Calories {cal} out of range")
                print("✗ Calories out of range")
            else:
                print(f"✓ Cals: {cal}")

            comp = m.get('dietary_compliance_pct')
            if comp < 0 or comp > 100:
                self.results['valid'] = False
                self.results['errors'].append(f"Day {m.get('day', i+1)}: Compliance {comp} invalid")
                print("✗ Compliance invalid")
            else:
                print(f"✓ Compliance: {comp}%")

       各种问题 = self.consecutive_same_category(menus)
        if各种问题:
            self.results['valid'] = False
            for bad in各种问题:
                self.results['errors'].append(f"Consecutive categories: from {bad['day1']} to {bad['day2']} ({bad['category']})")
                print(f"✗ Same category consecutive days")

       更多问题 = self.validate_compliance(menus)
        if更多问题:
            for bad in更多问题:
                self.results['errors'].append(f"Compliance invalid for {bad['day']}: {bad['value']}")

        return self.results

    def summarize(self, results: Dict, menus: List[Dict]) -> None:
        print("\n" + "=" * 60)
        if results['valid']:
            print("VALIDATION: ALL TESTS PASSED ✓")
        else:
            print("VALIDATION: TESTS FAILED ✗")
        print(f"Checked {len(menus)} menu entries")
        print(f"Calorie range: {min(c) if c else '?'}-{max(c) if c else '?'}")
        if results['errors']:
            print(f"Errors ({len(results['errors'])})")
            for err in results['errors']:
                print(f"  - {err}")


def main():
    print("Reading menus from evidence_based_menus.json...")
    menus = MenuValidator().read_menus('evidence_based_menus.json')
    print(f"Found {len(menus)} menus to validate")
    print("\nRunning validations:")
    results = MenuValidator().run_validations(menus)
    MenuValidator().summarize(results, menus)


if __name__ == "__main__":
    main()

