#!/usr/bin/env python3
"""
Build evidence-based weekly menus combining categorized recipes
with research findings to create scientifically grounded meal programs.
"""

import json
from typing import Dict, List

class MenuBuilder:
    """Class to build evidence-based weekly menus."""

    def __init__(self):
        self.recipes = []
        self.daily_menus = []

    def read_recipes(self, filepath: str) -> None:
        """Read recipes from JSON file."""
        try:
            with open(filepath, 'r') as f:
                self.recipes = json.load(f)
        except FileNotFoundError:
            pass

    def _get_category(self, recipe) -> str:
        """Extract recipe category from name."""
        name = recipe.get('name', '').lower()
        if 'vegeta' in name or 'cream' in name:
            return 'vegetable'
        if 'meat' in name:
            return 'meat'
        if 'soup' in name:
            return 'soup'
        if 'breakf' in name:
            return 'breakfast'
        if 'rice' in name or 'stap' in name:
            return 'staple'
        return 'other'

    def _assess_evidence_score(self, recipe) -> int:
        """Assign evidence score (1-5) based on research alignment."""
        name = recipe.get('name', '').lower()
        cat = self._get_category(recipe)

        base_scores = {
            'vegetable': 5, 'soup': 4, 'breakfast': 3, 'staple': 3, 
            'meat': 3, 'other': 2
        }
        score = base_scores.get(cat, 3)

        # Vegetarian recipes get full score
        if 'vegeta' in name or 'veg' in name:
            score = 5

        return min(5, max(1, score))

    def _estimate_calories(self, recipe) -> int:
        """Estimate calories based on category."""
        cat = self._get_category(recipe)
        cal_by_cat = {
            'vegetable': 350, 'soup': 300, 'breakfast': 400, 'staple': 500,
            'meat': 650, 'other': 425
        }
        return cal_by_cat.get(cat, 425)

    def _assess_compliance(self, total_calories) -> float:
        """Calculate dietary compliance (scaled 0-100)."""
        if 1800 <= total_calories <= 2200: return 85.0
        if total_calories > 2200: return max(35, 85 - (total_calories - 2200) / 5)
        return min(100, 85 + (1800 - total_calories) / 10)

    def add_menu(self, day, breakfast, lunch, dinner):
        """Add complete daily menu entry."""
        lunch_cal = self._estimate_calories(lunch)
        dinner_cal = self._estimate_calories(dinner)
        total_calories = 400 + lunch_cal + dinner_cal

        self.daily_menus.append({
            'day': day,
            'breakfast': breakfast,
            'lunch': lunch,
            'dinner': dinner,
            'estate_calories': str(int(total_calories)),
            'dietary_compliance_pct': round(self._assess_compliance(total_calories) * 10)
        })

    def _name_key(self, recipe) -> str:
        """Get recipe name as string for comparison."""
        return str(recipe.get('name', ''))

    def build_menu_for_day(self, used_names, day_idx, recipes) -> tuple:
        """Build menu for a day ensuring recipe variety."""
        # Find available recipes not used yet
        available = [(idx, r) for idx, r in enumerate(recipes) if self._name_key(r) not in used_names or self._name_key(r) == '']

        if available:
            sorted_avail = sorted(available, key=lambda x: (x[1].get('evidence_score', 1) or 1, x[0]), reverse=True)
            lunch = sorted_avail[0][1]
            used_names.add(self._name_key(lunch))
        else:
            lunch = recipes[0]
            used_names.add(self._name_key(lunch) if recipes else '')

        # Find dinner - different from lunch if possible
        other_recipes = [(idx, r) for idx, r in enumerate(recipes) 
                        if r != lunch and self._name_key(r) not in used_names]

        if other_recipes:
            sorted_other = sorted(other_recipes, key=lambda x: (x[1].get('evidence_score', 1) or 1, x[0]), reverse=True)
            dinner = sorted_other[0][1]
            used_names.add(self._name_key(dinner))
        else:
            dinner = lunch

        return lunch, dinner

    def _get_breakfast(self, day_idx) -> str:
        """Get breakfast option for given day."""
        breakfasts = ['Oatmeal with fruit', 'Whole grain toast with eggs', 'Greek yogurt parfait']
        return breakfasts[day_idx % 3]

    def build_menu_week(self) -> List:
        """Build complete 5-day menu plan."""
        if not self.recipes:
            print("Error: No recipes to build from")
            return []

        used_names = set()
        day_names = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday']
        # Breakfast options can rotate
        breakfasts = ['Oatmeal with fruit', 'Whole grain toast with eggs', 'Greek yogurt parfait']

        for day_idx, day in enumerate(day_names):
            # Build lunch and dinner for this day
            lunch, dinner = self.build_menu_for_day(used_names, day_idx, self.recipes)
            breakfast = self._get_breakfast(day_idx)

            self.add_menu(day, breakfast, lunch, dinner)

        return self.daily_menus

    def _get_caterogy(self, recipe) -> str:
        """Get category for recipe."""
        return self._get(category(recipe))

    def print_summary(self):
        """Print menu summary."""
        print("\n=== EVIDENCE-BASED WEEKLY MENUS ===")
        for menu in self.daily_menus:
            lacy = self._get_category(menu['lunch'])
            dacy = self._get_category(menu['dinner'])
            print(f"Day {menu['day']}:")
            print(f"  Breakfast: {menu['breakfast']}")
            print(f"  Lunch: {menu['lunch']['name']} [Cat: {lacy}, Evid: {menu['lunch'].get('evidence_score', 'N/A')}/5]")
            print(f"  Dinner: {menu['dinner']['name']} [Cat: {dacy}, Evid: {menu['dinner'].get('evidence_score', 'N/A')}/5]")
            print(f"  Calories: {menu['estate_calories']} | Compliance: {menu['dietary_compliance_pct']}%")

    def save_menus(self, filename='evidence_based_menus.json'):
        """Save menu data to file."""
        try:
            with open(filename, 'w', encoding='utf-8') as f:
                json.dump({'menus': self.daily_menus}, f, ensure_ascii=False, indent=2)
            print(f"\nMenus saved to {filename}")
        except Exception as e:
            print(f"Error saving: {e}")


def main():
    builder = MenuBuilder()
    builder.read_recipes('categorized_recipes.json')
    menus = builder.build_menu_week()
    builder.print_summary()
    builder.save_menus()


if __name__ == "__main__":
    main()

