                self.recipes = json.load(f)
        except FileNotFoundError:
            pass

    def _get_category(self, recipe: Dict) -> str:
        """Extract recipe category from name."""
        name = recipe.get('name', '').lower()
        if 'vegeta' in name or 'cream' in name:
            return 'vegetable'
        if 'meat' in name:
            return 'meat'
        if 'soup' in name:
            return 'soup'
        return 'other'

